import { useNavigate } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { useAuth } from '@/app/providers/AuthProvider'
import { useTenant } from '@/app/providers/TenantProvider'
import { useIdentity } from '@/app/providers/IdentityProvider'
import { PageHeader } from '@/features/shell/PageHeader'
import { ProjectCard } from '@/shared/ui/ProjectCard'
import { projectsService } from '@/integrations/supabase/projects'
import { Plus, ArrowRight } from 'lucide-react'

export function HomePage() {
  const { user } = useAuth()
  const { manifest } = useTenant()
  const navigate = useNavigate()
  const { activeWorkspace, centralUser } = useIdentity()
  const workplaceId = activeWorkspace?.id ?? ''
  const centralUserId = centralUser?.id ?? ''

  const { data: projects = [] } = useQuery({
    queryKey: ['projects', workplaceId, centralUserId],
    queryFn: () => projectsService.listProjects(workplaceId, centralUserId),
    enabled: !!workplaceId && !!centralUserId,
  })
  const recentProjects = projects.slice(0, 3)

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader
        title={`Welcome back${user ? `, ${user.displayName}` : ''}`}
        subtitle={manifest?.name}
      />
      <div className="flex-1 overflow-y-auto p-6">
        <div className="max-w-4xl mx-auto flex flex-col gap-8">

          <section>
            <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide mb-3">Quick actions</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {[
                { label: 'New project', icon: '📁', action: () => navigate('/app/projects') },
                { label: 'Browse marketplace', icon: '🛒', action: () => navigate('/marketplace/apps') },
                { label: 'My profile', icon: '👤', action: () => navigate('/app/profile') },
                { label: 'Settings', icon: '⚙️', action: () => navigate('/settings/account') },
              ].map((item) => (
                <button
                  key={item.label}
                  onClick={item.action}
                  className="flex flex-col gap-2 rounded-xl border border-border bg-surface p-4 text-left hover:border-accent/50 hover:bg-accent/5 transition-colors"
                >
                  <span className="text-2xl">{item.icon}</span>
                  <span className="text-sm font-medium">{item.label}</span>
                </button>
              ))}
            </div>
          </section>

          <section>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">Recent projects</h2>
              <button onClick={() => navigate('/app/projects')} className="flex items-center gap-1 text-xs text-accent hover:underline">
                View all <ArrowRight size={12} />
              </button>
            </div>
            {recentProjects.length === 0 ? (
              <div className="rounded-xl border border-dashed border-border p-8 text-center">
                <p className="text-sm text-muted-foreground mb-3">{workplaceId ? 'No projects yet' : 'Pick a workplace to see projects'}</p>
                <button onClick={() => navigate(workplaceId ? '/app/projects' : '/app/workplaces')} className="inline-flex items-center gap-1.5 text-sm text-accent hover:underline">
                  <Plus size={14} /> {workplaceId ? 'Create first project' : 'Choose workplace'}
                </button>
              </div>
            ) : (
              <div className="grid gap-3 md:grid-cols-2">
                {recentProjects.map((p) => (
                  <ProjectCard key={p.id} project={p} onClick={() => navigate(`/app/project/${p.id}/organiser`)} />
                ))}
              </div>
            )}
          </section>
        </div>
      </div>
    </div>
  )
}
